/**
 * Serves web/'s static files — the reviewer PWA itself (index.html/app.js,
 * scan.html/scan.js, stats.html/stats.js, offline.js, auth.js, sw.js, theme.css).
 *
 * Exists because web/ had nowhere to run: no build step, no hosting config
 * anywhere in this repo, and every fetch in app.js/scan.js/stats.js used a
 * same-origin relative path with no base URL — none of which is Supabase's own
 * routing (confirmed against Supabase's own docs, not assumed: a deployed edge
 * function's paths are always prefixed with its own slug, e.g. /sync/... for
 * the sync function — there is no way to serve anything at bare root). Rather
 * than pick an external static host (a second account, a second deploy step, a
 * decision this repo shouldn't make silently) and wire up CORS across two
 * origins, this serves web/ from the same Supabase project as sync/scan/
 * pronounce — matching D6 ("one deploy target") exactly, and same-origin, so
 * no CORS is needed at all. The client files build every API URL as
 * /functions/v1/<slug>/... (see their own comments) to match.
 *
 * Files are embedded as string constants, not read from disk at request time —
 * checked against reality, not assumed: Deno.readFile relative to import.meta.url
 * does NOT reach files that were only uploaded alongside the entrypoint (never
 * imported as a module) — Supabase's edge runtime flattens a deployed function's
 * own directory to /var/tmp/sb-compile-edge-runtime/<slug>/, discarding the
 * original supabase/functions/app/ nesting; confirmed directly via this
 * function's own logs after the first version 404'd on every request. Embedding
 * sidesteps that entirely — these are part of the compiled module, not a runtime
 * filesystem lookup.
 *
 * This file is generated (see the repo's own build note below) from the real
 * contents of web/ — never hand-edit the embedded strings here; edit web/
 * itself and regenerate.
 *
 * url.pathname inside this handler has already had /functions/v1 stripped by
 * the platform, same as every other function here — what's left is /app/...
 * (this function's own slug prefix), stripped below to find the file. A request
 * for /app or /app/ (no file) serves index.html.
 *
 * **KNOWN GAP, deployed but not usable as-is: Supabase rewrites every
 * `text/html` GET response from an edge function to `text/plain`, undocumented
 * in this repo until hit live** (Supabase's own docs, found only after
 * deploying: "HTML content is not supported... will be rewritten to
 * text/plain. Edge Functions are designed for APIs... not serving web pages").
 * Confirmed directly: `curl -I` on `index.html` shows the correct
 * `text/html` header, `.js`/`.css` files serve and execute fine, but a real
 * browser renders `index.html`/`scan.html`/`stats.html` as escaped plain text,
 * never as a page — this is a platform rewrite, not something a response
 * header here can override. Two real fixes, neither applied yet: serve the
 * HTML as `application/xhtml+xml` instead (the markup already uses
 * self-closing tags in the right places, untested whether real browsers treat
 * it as a page) or move `web/` to a real static host (GitHub Pages is the
 * obvious one, already have access) with CORS added to `sync`/`scan`/
 * `pronounce` and the client's `API_BASE` becoming a real per-instance URL
 * instead of the relative `/functions/v1` path it is today.
 */

interface StaticFile {
  content: string;
  contentType: string;
}

const FILES: Record<string, StaticFile> = {
  "index.html": { content: "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>Capybara</title>\n<link rel=\"stylesheet\" href=\"theme.css\" />\n<style>\n  /* Palette matches AnkiDroid's own night theme as closely as CSS reasonably\n     allows: near-black surfaces at two elevations (toolbar/stats strip a shade\n     lighter than the card body), the same new/learning/review color convention\n     (blue/red/green), and the same button treatment (Again/Good/Easy solid-filled,\n     Hard visually quieter). Light mode is a straight inversion for anyone who\n     isn't in night mode — Anki supports both, so this does too. Color tokens and\n     toolbar chrome live in theme.css, shared with scan.html. */\n  #stats-strip {\n    display: flex;\n    gap: 16px;\n    padding: 8px 16px;\n    background: var(--bg-toolbar);\n    border-bottom: 1px solid var(--border);\n    font-size: 14px;\n    font-variant-numeric: tabular-nums;\n  }\n  /* .new/.learning/.review/.pending moved to theme.css — stats.html's collection\n     composition blocks need the same three colors, and the bug that made this\n     class-not-container-scoped in the first place (see theme.css's own comment)\n     applies just as much across pages as within one. */\n\n  /* Deck list */\n  .deck-row {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 16px 4px;\n    border-bottom: 1px solid var(--border);\n    cursor: pointer;\n  }\n  .deck-row:hover { background: var(--bg-toolbar); }\n  .deck-name { font-size: 16px; }\n  .deck-counts { display: flex; gap: 12px; font-size: 15px; font-variant-numeric: tabular-nums; }\n  #session-footer {\n    text-align: center;\n    color: var(--fg-muted);\n    font-size: 13px;\n    padding: 20px 0;\n  }\n  #session-footer a { color: var(--fg-muted); text-decoration: underline; }\n\n  /* Card */\n  #card {\n    padding: 32px 4px;\n    text-align: center;\n    min-height: 55vh;\n    display: flex;\n    flex-direction: column;\n    gap: 10px;\n  }\n  #lemma { font-size: 30px; font-weight: 600; }\n  #back { display: none; flex-direction: column; gap: 8px; }\n  #back.visible { display: flex; }\n  hr.divider { width: 100%; border: none; border-top: 1px solid var(--border); margin: 4px 0; }\n  .translation { font-size: 22px; }\n  .gloss { color: var(--fg-muted); }\n  .pos { font-size: 13px; color: var(--fg-muted); font-style: italic; }\n  .example { margin-top: 14px; }\n  .example-translation { color: var(--fg-muted); font-size: 15px; }\n\n  #answer-bar { position: fixed; bottom: 0; left: 0; right: 0; }\n  #reveal-btn {\n    width: 100%;\n    padding: 18px;\n    border: none;\n    background: var(--btn-reveal);\n    color: var(--btn-fg);\n    font-size: 16px;\n    cursor: pointer;\n  }\n  #rating-row { display: flex; }\n  #rating-row button {\n    flex: 1;\n    border: none;\n    padding: 10px 4px 16px;\n    color: var(--btn-fg);\n    font-size: 15px;\n    cursor: pointer;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n  }\n  #rating-row .interval { font-size: 12px; opacity: 0.85; }\n  .rating-again { background: var(--btn-again); }\n  .rating-hard { background: var(--btn-hard-bg); color: var(--btn-hard-fg); }\n  .rating-good { background: var(--btn-good); }\n  .rating-easy { background: var(--btn-easy); }\n\n  #tools-row { display: flex; gap: 8px; justify-content: center; margin-top: 20px; }\n  #tools-row button {\n    background: none;\n    border: 1px solid var(--border);\n    border-radius: 6px;\n    color: var(--fg-muted);\n    font-size: 13px;\n    padding: 6px 12px;\n    cursor: pointer;\n  }\n\n  #edit-form { display: none; flex-direction: column; gap: 10px; text-align: left; padding-top: 8px; }\n  #edit-form.visible { display: flex; }\n  #edit-form label { font-size: 12px; color: var(--fg-muted); }\n  #edit-form input {\n    width: 100%;\n    padding: 9px;\n    border-radius: 6px;\n    border: 1px solid var(--border);\n    background: var(--bg-page);\n    color: var(--fg);\n    font-size: 14px;\n  }\n  #edit-errors { color: var(--btn-again); font-size: 13px; }\n\n  #empty, #error { text-align: center; padding: 60px 16px; color: var(--fg-muted); }\n\n  /* Pronunciation (D18) — record-and-score instead of reveal-and-rate. */\n  #pronunciation-control { margin: 24px 0; }\n  .mic-btn {\n    width: 84px;\n    height: 84px;\n    border-radius: 50%;\n    border: none;\n    font-size: 32px;\n    cursor: pointer;\n    background: var(--btn-good);\n    color: var(--btn-fg);\n  }\n  .mic-btn.recording { background: var(--btn-again); }\n  #pronunciation-status { color: var(--fg-muted); font-size: 13px; margin-top: 8px; }\n  #pronunciation-result {\n    margin: 16px 0;\n    padding: 14px;\n    border-radius: 8px;\n    background: var(--bg-toolbar);\n  }\n  .bucket-label { font-size: 18px; font-weight: 700; letter-spacing: 0.04em; }\n  #pronunciation-result.bucket-right .bucket-label { color: var(--stat-review); }\n  #pronunciation-result.bucket-close .bucket-label { color: var(--btn-hard-fg); }\n  #pronunciation-result.bucket-wrong .bucket-label { color: var(--btn-again); }\n  #pronunciation-result .transcript { margin-top: 6px; font-style: italic; color: var(--fg-muted); }\n  #pronunciation-error { color: var(--btn-again); font-size: 13px; margin-top: 8px; }\n  #continue-btn {\n    width: 100%;\n    padding: 14px;\n    border: none;\n    border-radius: 8px;\n    background: var(--btn-reveal);\n    color: var(--btn-fg);\n    font-size: 15px;\n    cursor: pointer;\n    margin-top: 8px;\n  }\n  .card-kind-badge {\n    /* #card is a flex column with default align-items: stretch — without\n       align-self here this stretches to the card's full width instead of\n       sizing to its own text (caught by a Playwright screenshot showing a\n       full-width pill instead of a small badge). */\n    align-self: center;\n    font-size: 11px;\n    color: var(--fg-muted);\n    border: 1px solid var(--border);\n    border-radius: 4px;\n    padding: 2px 8px;\n    margin-bottom: 8px;\n  }\n</style>\n</head>\n<body>\n<div id=\"toolbar\">\n  <button id=\"back-btn\" class=\"icon-btn\" hidden>←</button>\n  <h1 id=\"title\">Capybara</h1>\n  <a id=\"scan-link\" class=\"icon-btn\" href=\"./scan.html\" hidden>📷</a>\n</div>\n<div id=\"stats-strip\" hidden></div>\n<main id=\"content\"><div id=\"loading\" style=\"padding: 40px; text-align: center; color: var(--fg-muted)\">Loading…</div></main>\n<script type=\"module\" src=\"app.js\"></script>\n</body>\n</html>\n", contentType: "text/html; charset=utf-8" },
  "app.js": { content: "// The reviewer — step 2 of docs/DESIGN.md's build order, redesigned to match\n// AnkiDroid's own layout and dark theme after seeing real screenshots of it (deck\n// list with new/learning/review counts, the stats strip, card front/back\n// hierarchy, the four-button rating bar). Still deliberately plain JS, no build\n// step: every scheduling decision lives server-side (src/review/), so this file's\n// job is fetch → render → post an answer → next card.\n//\n// Every deck a note actually exists in shows up here — there's no hardcoded deck\n// list. Grammar is just vocabulary notes in a differently-named deck (confirmed\n// against a real export, docs/DESIGN.md D17/§11 item 4) and needs nothing special.\n// Pronunciation notes (D18) share the same `notes` row shape too, just with\n// `kind: \"pronunciation\"` and a different reveal-and-rate UI (renderReview()\n// branches on it below) — recording and scoring an attempt instead of a\n// self-graded four-button tap. Spelling (D17's `card_kind`) surfaces as a second\n// due item alongside a `Capybara+` note's normal recall card, not a separate deck.\n//\n// Auth (D13, §4.5): install is opening one link, `#t=<token>`. `auth.js` (shared\n// with scan.js) reads the fragment, stores the token, and strips it from the\n// visible URL and history so it never lingers there or gets shared by accident —\n// this file just sends it as a bearer token on every call.\n//\n// Offline (step 3, §6): `offline.js` is the IndexedDB-backed review queue and\n// response cache; `api()` below is the one place that decides when to fall back to\n// it, so every call site (submitRating, refreshStatsStrip, enterDeck, …) stays\n// offline-safe automatically rather than each needing its own try/catch.\n\nimport * as offline from \"./offline.js\";\nimport { captureTokenFromUrl, getToken } from \"./auth.js\";\n\n// Supabase Edge Functions are always reached under /functions/v1/<slug> — there is\n// no way to serve them at bare root (confirmed against Supabase's own routing docs,\n// not assumed). This app is hosted BY one of those functions too (`app`), so every\n// API path below (still written as e.g. \"/sync/review\" everywhere it's used as an\n// identifier — cache keys, the offline-queue comparison below) gets this prefix\n// applied at the one point it actually becomes a fetch URL, not baked into the\n// literal itself.\nconst API_BASE = \"/functions/v1\";\n\nasync function api(path, options = {}) {\n  const token = getToken();\n  const method = options.method ?? \"GET\";\n  try {\n    const res = await fetch(API_BASE + path, {\n      ...options,\n      headers: {\n        \"content-type\": \"application/json\",\n        ...(token ? { authorization: `Bearer ${token}` } : {}),\n        ...options.headers,\n      },\n    });\n    if (!res.ok && res.status !== 400) {\n      throw new Error(`${method} ${path} -> ${res.status}`);\n    }\n    const data = await res.json();\n    if (method === \"GET\") await offline.cacheResponse(path, data);\n    return data;\n  } catch (e) {\n    // A TypeError here is fetch itself failing (no network) — distinct from a real\n    // non-2xx response above, which propagates as-is (saveEdit()'s error-message\n    // path depends on that). Offline, a queued review or a cached GET keeps the\n    // session going instead of surfacing an error for something §6 says shouldn't\n    // interrupt a review session.\n    if (e instanceof TypeError) {\n      if (method === \"POST\" && path === \"/sync/review\") {\n        await offline.queueReview(JSON.parse(options.body));\n        return { ok: true, queued: true };\n      }\n      if (method === \"GET\") {\n        const cached = await offline.getCachedResponse(path);\n        if (cached !== undefined) return cached;\n      }\n    }\n    throw e;\n  }\n}\n\nconst contentEl = document.getElementById(\"content\");\nconst titleEl = document.getElementById(\"title\");\nconst backBtn = document.getElementById(\"back-btn\");\nconst scanLink = document.getElementById(\"scan-link\");\nconst statsStrip = document.getElementById(\"stats-strip\");\n\nconst state = {\n  view: \"decks\", // \"decks\" | \"review\"\n  decks: [],\n  currentDeck: null,\n  queue: [],\n  index: 0,\n  revealed: false,\n  editing: false,\n  sessionCount: 0,\n  // D18 (pronunciation notes): \"idle\" | \"recording\" | \"scoring\" | \"scored\".\n  recording: \"idle\",\n  pronunciationResult: null, // { transcript, similarity, bucket, rating } | { error } | null\n};\n\n/** Formats a due date as AnkiDroid's own short interval label (\"<1m\", \"10m\", \"4d\",\n * \"3.2mo\") — relative to now, since that's what the button is telling the person:\n * how long until this comes back if they tap it. */\nfunction formatInterval(dueIso, now) {\n  const ms = new Date(dueIso).getTime() - now.getTime();\n  const minutes = ms / 60_000;\n  if (minutes < 1) return \"<1m\";\n  if (minutes < 60) return `${Math.round(minutes)}m`;\n  const hours = minutes / 60;\n  if (hours < 24) return `${Math.round(hours)}h`;\n  const days = hours / 24;\n  if (days < 30) return `${Math.round(days)}d`;\n  const months = days / 30;\n  if (months < 12) return `${months.toFixed(1)}mo`;\n  return `${(days / 365).toFixed(1)}y`;\n}\n\nfunction escapeHtml(s) {\n  return (s ?? \"\").replace(/[&<>\"']/g, (c) => ({\n    \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\",\n  }[c]));\n}\n\nbackBtn.addEventListener(\"click\", showDeckList);\n\n// ---------------------------------------------------------------------------\n// Deck list\n// ---------------------------------------------------------------------------\n\nasync function showDeckList() {\n  state.view = \"decks\";\n  backBtn.hidden = true;\n  scanLink.hidden = false;\n  titleEl.textContent = \"Capybara\";\n  statsStrip.hidden = true;\n\n  contentEl.innerHTML = `<div style=\"padding: 40px; text-align: center; color: var(--fg-muted)\">Loading…</div>`;\n  try {\n    state.decks = await api(\"/sync/decks\");\n  } catch (e) {\n    contentEl.innerHTML = `<div id=\"error\">Couldn't load decks.</div>`;\n    console.error(e);\n    return;\n  }\n  renderDeckList();\n}\n\nfunction renderDeckList() {\n  const totalDue = state.decks.reduce((sum, d) => sum + d.newCount + d.learningCount + d.reviewCount, 0);\n  titleEl.textContent = `Capybara — ${totalDue} due`;\n\n  contentEl.innerHTML = `\n    ${\n      state.decks.map((d) => `\n        <div class=\"deck-row\" data-deck=\"${escapeHtml(d.deck)}\">\n          <span class=\"deck-name\">${escapeHtml(d.deck)}</span>\n          <span class=\"deck-counts\">\n            <span class=\"new\">${d.newCount}</span>\n            <span class=\"learning\">${d.learningCount}</span>\n            <span class=\"review\">${d.reviewCount}</span>\n          </span>\n        </div>\n      `).join(\"\")\n    }\n    <div id=\"session-footer\">\n      Studied ${state.sessionCount} card${state.sessionCount === 1 ? \"\" : \"s\"} this session\n      · <a href=\"./stats.html\">Stats</a>\n    </div>\n  `;\n  contentEl.querySelectorAll(\".deck-row\").forEach((row) => {\n    row.addEventListener(\"click\", () => enterDeck(row.dataset.deck));\n  });\n}\n\n// ---------------------------------------------------------------------------\n// Review\n// ---------------------------------------------------------------------------\n\nasync function enterDeck(deck) {\n  state.view = \"review\";\n  state.currentDeck = deck;\n  state.index = 0;\n  state.revealed = false;\n  state.editing = false;\n  backBtn.hidden = false;\n  scanLink.hidden = true;\n  titleEl.textContent = deck;\n\n  contentEl.innerHTML = `<div style=\"padding: 40px; text-align: center; color: var(--fg-muted)\">Loading…</div>`;\n  try {\n    state.queue = await api(`/sync/due?deck=${encodeURIComponent(deck)}`);\n  } catch (e) {\n    contentEl.innerHTML = `<div id=\"error\">Couldn't load this deck.</div>`;\n    console.error(e);\n    return;\n  }\n  await updateStatsStrip();\n  renderReview();\n}\n\nfunction currentNote() {\n  return state.queue[state.index] ?? null;\n}\n\nasync function updateStatsStrip() {\n  const deckSummary = state.decks.find((d) => d.deck === state.currentDeck);\n  if (!deckSummary) {\n    statsStrip.hidden = true;\n    return;\n  }\n  const pending = await offline.pendingReviewCount();\n  statsStrip.hidden = false;\n  statsStrip.innerHTML = `\n    <span class=\"new\">${deckSummary.newCount}</span>\n    <span class=\"learning\">${deckSummary.learningCount}</span>\n    <span class=\"review\">${deckSummary.reviewCount}</span>\n    ${pending > 0 ? `<span class=\"pending\">⟳ ${pending}</span>` : \"\"}\n  `;\n}\n\n/** Refreshes the stats strip from the server after an answer — matching real\n * Anki's live countdown, but by asking rather than guessing. An earlier version\n * of this tried to derive \"was this card new or review\" client-side from queue\n * position; that's exactly the kind of scheduling classification src/review/\n * already does correctly and the client has no business re-deriving badly.\n * Offline, `api()` falls back to the last cached `/sync/decks` response, so this\n * still renders something rather than throwing mid-session. */\nasync function refreshStatsStrip() {\n  state.decks = await api(\"/sync/decks\");\n  await updateStatsStrip();\n}\n\n/** Pushes every locally-queued review to the server, oldest first, stopping at the\n * first failure (still offline, or a genuine server error) rather than reordering\n * around it — §6's \"reconnect\" row: the queue flushes as a batch, and a\n * client-generated `reviewId` (already required by `/sync/review`) makes a review\n * that already landed on a previous attempt a no-op instead of a duplicate. */\nasync function flushPendingReviews() {\n  const pending = await offline.listPendingReviews();\n  for (const review of pending) {\n    const token = getToken();\n    if (!token) return;\n    let res;\n    try {\n      res = await fetch(API_BASE + \"/sync/review\", {\n        method: \"POST\",\n        headers: { \"content-type\": \"application/json\", authorization: `Bearer ${token}` },\n        body: JSON.stringify(review),\n      });\n    } catch {\n      return; // still offline — try again on the next 'online' event\n    }\n    if (!res.ok) return; // a real server error; stop rather than lose ordering\n    await offline.removePendingReview(review.reviewId);\n  }\n  if (state.view === \"review\") await refreshStatsStrip();\n  else if (state.view === \"decks\") await showDeckList();\n}\n\nglobalThis.addEventListener(\"online\", flushPendingReviews);\n\nfunction renderReview() {\n  const note = currentNote();\n  if (!note) {\n    contentEl.innerHTML = `<div id=\"empty\">Nothing due in ${escapeHtml(state.currentDeck)} right now. 🎉</div>`;\n    return;\n  }\n\n  if (state.editing) {\n    renderEditForm(note);\n    return;\n  }\n\n  if (note.kind === \"pronunciation\") {\n    renderPronunciationReview(note);\n    return;\n  }\n\n  contentEl.innerHTML = `\n    <div id=\"card\">\n      ${note.cardKind === \"spelling\" ? `<div class=\"card-kind-badge\">Spelling</div>` : \"\"}\n      <div id=\"lemma\">${escapeHtml(note.lemma)}</div>\n      <div id=\"back\" class=\"${state.revealed ? \"visible\" : \"\"}\">\n        <hr class=\"divider\" />\n        <div class=\"translation\">${escapeHtml(note.lemmaTranslation)}</div>\n        <div class=\"gloss\">${escapeHtml(note.gloss)}</div>\n        <div class=\"pos\">${[note.partOfSpeech, note.language].filter(Boolean).join(\" · \")}</div>\n        <hr class=\"divider\" />\n        ${note.example ? `<div class=\"example\">${escapeHtml(note.example)}</div>` : \"\"}\n        ${note.exampleTranslation ? `<div class=\"example-translation\">${escapeHtml(note.exampleTranslation)}</div>` : \"\"}\n      </div>\n      <div id=\"tools-row\">\n        <button id=\"edit\">Edit</button>\n        <button id=\"suspend\">Suspend</button>\n        <button id=\"delete\">Delete</button>\n      </div>\n    </div>\n    <div id=\"answer-bar\">\n      ${\n        state.revealed\n          ? (() => {\n              const now = new Date();\n              const p = note.preview;\n              return `<div id=\"rating-row\">\n               <button class=\"rating-again\" data-rating=\"1\"><span class=\"interval\">${formatInterval(p.again, now)}</span><span>Again</span></button>\n               <button class=\"rating-hard\" data-rating=\"2\"><span class=\"interval\">${formatInterval(p.hard, now)}</span><span>Hard</span></button>\n               <button class=\"rating-good\" data-rating=\"3\"><span class=\"interval\">${formatInterval(p.good, now)}</span><span>Good</span></button>\n               <button class=\"rating-easy\" data-rating=\"4\"><span class=\"interval\">${formatInterval(p.easy, now)}</span><span>Easy</span></button>\n             </div>`;\n            })()\n          : `<button id=\"reveal-btn\">Show answer</button>`\n      }\n    </div>\n  `;\n\n  document.getElementById(\"reveal-btn\")?.addEventListener(\"click\", () => {\n    state.revealed = true;\n    renderReview();\n  });\n  contentEl.querySelectorAll(\"[data-rating]\").forEach((btn) => {\n    btn.addEventListener(\"click\", () => submitRating(Number(btn.dataset.rating)));\n  });\n  document.getElementById(\"edit\").addEventListener(\"click\", () => {\n    state.editing = true;\n    renderReview();\n  });\n  document.getElementById(\"suspend\").addEventListener(\"click\", suspendCurrent);\n  document.getElementById(\"delete\").addEventListener(\"click\", deleteCurrent);\n}\n\nfunction renderEditForm(note) {\n  const fields = [\n    [\"lemma\", \"Lemma\"],\n    [\"gloss\", \"Gloss\"],\n    [\"lemmaTranslation\", \"Translation\"],\n    [\"partOfSpeech\", \"Part of speech\"],\n    [\"example\", \"Example\"],\n    [\"exampleTranslation\", \"Example translation\"],\n  ];\n  contentEl.innerHTML = `\n    <div id=\"edit-form\" class=\"visible\">\n      ${\n        fields.map(([key, label]) => `\n          <label>${label}\n            <input data-field=\"${key}\" value=\"${escapeHtml(note[key])}\" />\n          </label>\n        `).join(\"\")\n      }\n      <div id=\"edit-errors\"></div>\n      <div id=\"tools-row\">\n        <button id=\"save\">Save</button>\n        <button id=\"cancel\">Cancel</button>\n      </div>\n    </div>\n  `;\n  document.getElementById(\"cancel\").addEventListener(\"click\", () => {\n    state.editing = false;\n    renderReview();\n  });\n  document.getElementById(\"save\").addEventListener(\"click\", () => saveEdit(note));\n}\n\nasync function saveEdit(note) {\n  const patch = {};\n  contentEl.querySelectorAll(\"[data-field]\").forEach((input) => {\n    patch[input.dataset.field] = input.value;\n  });\n  const result = await api(`/sync/note/${note.id}`, { method: \"PATCH\", body: JSON.stringify(patch) });\n  if (!result.ok) {\n    document.getElementById(\"edit-errors\").textContent = result.errors.join(\"; \");\n    return;\n  }\n  Object.assign(note, patch);\n  state.editing = false;\n  renderReview();\n}\n\nasync function submitRating(rating) {\n  const note = currentNote();\n  await api(\"/sync/review\", {\n    method: \"POST\",\n    body: JSON.stringify({\n      reviewId: crypto.randomUUID(),\n      noteId: note.id,\n      cardKind: note.cardKind,\n      rating,\n      reviewedAt: new Date().toISOString(),\n    }),\n  });\n  state.sessionCount++;\n  await refreshStatsStrip();\n  advance();\n}\n\nasync function suspendCurrent() {\n  const note = currentNote();\n  await api(\"/sync/suspend\", {\n    method: \"POST\",\n    body: JSON.stringify({ noteId: note.id, cardKind: note.cardKind, suspended: true }),\n  });\n  advance();\n}\n\nasync function deleteCurrent() {\n  const note = currentNote();\n  if (!confirm(`Delete \"${note.lemma}\" permanently? This removes its review history too.`)) return;\n  await api(`/sync/note/${note.id}`, { method: \"DELETE\" });\n  advance();\n}\n\nfunction advance() {\n  state.queue.splice(state.index, 1);\n  state.revealed = false;\n  state.editing = false;\n  state.recording = \"idle\";\n  state.pronunciationResult = null;\n  renderReview();\n}\n\n// ---------------------------------------------------------------------------\n// Pronunciation (D18) — record an attempt, score it via /pronounce/score,\n// submit the resulting rating through the exact same /sync/review submitRating()\n// every other card uses. No separate scheduling path for pronunciation notes —\n// only a different way of arriving at a rating.\n// ---------------------------------------------------------------------------\n\nlet mediaRecorder = null;\nlet recordedChunks = [];\n\nfunction blobToBase64(blob) {\n  return new Promise((resolve, reject) => {\n    const reader = new FileReader();\n    reader.onload = () => resolve(reader.result.slice(reader.result.indexOf(\",\") + 1));\n    reader.onerror = () => reject(reader.error);\n    reader.readAsDataURL(blob);\n  });\n}\n\nasync function startRecording() {\n  let stream;\n  try {\n    stream = await navigator.mediaDevices.getUserMedia({ audio: true });\n  } catch (e) {\n    console.error(e);\n    state.pronunciationResult = { error: \"Microphone access was denied or unavailable.\" };\n    renderReview();\n    return;\n  }\n  recordedChunks = [];\n  mediaRecorder = new MediaRecorder(stream);\n  mediaRecorder.addEventListener(\"dataavailable\", (e) => {\n    if (e.data.size > 0) recordedChunks.push(e.data);\n  });\n  mediaRecorder.start();\n  state.recording = \"recording\";\n  state.pronunciationResult = null;\n  renderReview();\n}\n\nfunction stopRecording() {\n  return new Promise((resolve) => {\n    mediaRecorder.addEventListener(\"stop\", () => {\n      const blob = new Blob(recordedChunks, { type: mediaRecorder.mimeType || \"audio/webm\" });\n      mediaRecorder.stream.getTracks().forEach((track) => track.stop());\n      resolve(blob);\n    }, { once: true });\n    mediaRecorder.stop();\n  });\n}\n\nasync function stopAndScore() {\n  const blob = await stopRecording();\n  state.recording = \"scoring\";\n  renderReview();\n\n  try {\n    const audioBase64 = await blobToBase64(blob);\n    const result = await api(\"/pronounce/score\", {\n      method: \"POST\",\n      body: JSON.stringify({\n        noteId: currentNote().id,\n        audioBase64,\n        mediaType: blob.type || \"audio/webm\",\n      }),\n    });\n    state.pronunciationResult = result;\n    state.recording = \"scored\";\n  } catch (e) {\n    console.error(e);\n    state.pronunciationResult = { error: e.message ?? \"Scoring failed. Try again.\" };\n    state.recording = \"idle\";\n  }\n  renderReview();\n}\n\n/** The rating a scored attempt produced goes through submitRating() unchanged —\n * pronunciation notes only ever have a 'recall' card (never hasSpelling), so\n * currentNote().cardKind is always right for the /sync/review call it makes. */\nasync function continueAfterScore() {\n  const rating = state.pronunciationResult.rating;\n  await submitRating(rating);\n}\n\nfunction renderPronunciationReview(note) {\n  const result = state.pronunciationResult;\n  contentEl.innerHTML = `\n    <div id=\"card\">\n      <div id=\"lemma\">${escapeHtml(note.lemma)}</div>\n      <div class=\"translation\">${escapeHtml(note.lemmaTranslation)}</div>\n      ${note.gloss ? `<div class=\"gloss\">${escapeHtml(note.gloss)}</div>` : \"\"}\n      ${note.audioUrl ? `<audio controls src=\"${escapeHtml(note.audioUrl)}\" style=\"margin-top: 12px\"></audio>` : \"\"}\n\n      <div id=\"pronunciation-control\">\n        ${\n          state.recording === \"recording\"\n            ? `<button id=\"mic-btn\" class=\"mic-btn recording\">⏹</button>\n               <div id=\"pronunciation-status\">Recording — tap to stop</div>`\n            : state.recording === \"scoring\"\n            ? `<button class=\"mic-btn\" disabled>…</button>\n               <div id=\"pronunciation-status\">Scoring…</div>`\n            : `<button id=\"mic-btn\" class=\"mic-btn\">🎤</button>\n               <div id=\"pronunciation-status\">Tap to record yourself saying this</div>`\n        }\n      </div>\n\n      ${\n        result && !result.error\n          ? `<div id=\"pronunciation-result\" class=\"bucket-${result.bucket}\">\n               <div class=\"bucket-label\">${result.bucket.toUpperCase()}</div>\n               <div class=\"transcript\">Heard: \"${escapeHtml(result.transcript)}\"</div>\n             </div>\n             <button id=\"continue-btn\">Continue</button>`\n          : \"\"\n      }\n      ${result?.error ? `<div id=\"pronunciation-error\">${escapeHtml(result.error)}</div>` : \"\"}\n\n      <div id=\"tools-row\">\n        <button id=\"suspend\">Suspend</button>\n        <button id=\"delete\">Delete</button>\n      </div>\n    </div>\n  `;\n\n  const micBtn = document.getElementById(\"mic-btn\");\n  if (micBtn && state.recording === \"idle\") micBtn.addEventListener(\"click\", startRecording);\n  if (micBtn && state.recording === \"recording\") micBtn.addEventListener(\"click\", stopAndScore);\n  document.getElementById(\"continue-btn\")?.addEventListener(\"click\", continueAfterScore);\n  document.getElementById(\"suspend\").addEventListener(\"click\", suspendCurrent);\n  document.getElementById(\"delete\").addEventListener(\"click\", deleteCurrent);\n}\n\n// ---------------------------------------------------------------------------\n\nasync function main() {\n  captureTokenFromUrl();\n  if (!getToken()) {\n    contentEl.innerHTML = `<div id=\"error\">No access token. Open your install link again.</div>`;\n    return;\n  }\n  if (\"serviceWorker\" in navigator) {\n    navigator.serviceWorker.register(\"./sw.js\").catch((e) => console.error(\"sw registration failed\", e));\n  }\n  if (navigator.onLine) await flushPendingReviews(); // queued from a previous offline stretch\n  await showDeckList();\n}\n\nmain();\n", contentType: "text/javascript; charset=utf-8" },
  "auth.js": { content: "// D13's device token (§4.5), shared by every page in web/ (index.html's app.js,\n// scan.html's scan.js) — both need exactly the same \"read the fragment, remember\n// it, hand it back as a bearer token\" logic, so it lives here once rather than\n// twice.\n\nconst TOKEN_KEY = \"capybara-anki-token\";\n\n/** Install is opening one link, `#t=<token>`. Reads the fragment, stores the\n * token, and strips it from the visible URL and history so it never lingers there\n * or gets shared by accident. `location.hash` includes its own leading \"#\" (e.g.\n * \"#t=abc\"), which `URLSearchParams` doesn't expect — stripped here before\n * parsing, not after (a real bug the first version of this had, caught with\n * Playwright: a fresh install link never actually stored its token). */\nexport function captureTokenFromUrl() {\n  const params = new URLSearchParams(location.hash.slice(1));\n  const token = params.get(\"t\");\n  if (!token) return;\n  localStorage.setItem(TOKEN_KEY, token);\n  history.replaceState(null, \"\", location.pathname + location.search);\n}\n\nexport function getToken() {\n  return localStorage.getItem(TOKEN_KEY);\n}\n", contentType: "text/javascript; charset=utf-8" },
  "offline.js": { content: "// Offline support (step 3, docs/DESIGN.md §6) — an IndexedDB-backed queue for\n// reviews submitted while offline, plus a cache of the last-fetched due queue and\n// deck list so a reload while still offline shows something instead of \"Loading…\"\n// forever. Deliberately narrow, matching §6's table: only *reviews* are queued for\n// replay (client-generated `reviewId` makes a retried or double-submitted review an\n// idempotent no-op server-side, per §4.2 — reviewing the same card twice during one\n// offline stretch after a reload is harmless for the same reason, just two real\n// events instead of one). Suspend/edit/delete are not queued — they're rarer\n// mid-session actions, and failing them visibly while offline is more honest than\n// queuing a delete that might race a review of the same note.\n\nconst DB_NAME = \"capybara-anki\";\nconst DB_VERSION = 1;\nconst PENDING_REVIEWS_STORE = \"pendingReviews\";\nconst CACHE_STORE = \"cachedResponses\";\n\nfunction openDb() {\n  return new Promise((resolve, reject) => {\n    const req = indexedDB.open(DB_NAME, DB_VERSION);\n    req.onupgradeneeded = () => {\n      const db = req.result;\n      if (!db.objectStoreNames.contains(PENDING_REVIEWS_STORE)) {\n        db.createObjectStore(PENDING_REVIEWS_STORE, { keyPath: \"reviewId\" });\n      }\n      if (!db.objectStoreNames.contains(CACHE_STORE)) {\n        db.createObjectStore(CACHE_STORE, { keyPath: \"key\" });\n      }\n    };\n    req.onsuccess = () => resolve(req.result);\n    req.onerror = () => reject(req.error);\n  });\n}\n\nfunction runTx(db, storeName, mode, fn) {\n  return new Promise((resolve, reject) => {\n    const tx = db.transaction(storeName, mode);\n    const store = tx.objectStore(storeName);\n    const result = fn(store);\n    tx.oncomplete = () => resolve(result);\n    tx.onerror = () => reject(tx.error);\n  });\n}\n\n/** Queues a review submitted while offline. `review` is exactly the body\n * `/sync/review` expects (`{reviewId, noteId, rating, reviewedAt}`). */\nexport async function queueReview(review) {\n  const db = await openDb();\n  await runTx(db, PENDING_REVIEWS_STORE, \"readwrite\", (store) => store.put(review));\n}\n\n/** Every review not yet confirmed synced, oldest first (insertion order — IndexedDB\n * cursors over a keyPath store don't guarantee this on their own, so this reads via\n * getAll and relies on `reviewedAt` for ordering instead of trusting store order). */\nexport async function listPendingReviews() {\n  const db = await openDb();\n  const all = await new Promise((resolve, reject) => {\n    const req = db.transaction(PENDING_REVIEWS_STORE, \"readonly\")\n      .objectStore(PENDING_REVIEWS_STORE)\n      .getAll();\n    req.onsuccess = () => resolve(req.result);\n    req.onerror = () => reject(req.error);\n  });\n  return all.sort((a, b) => new Date(a.reviewedAt) - new Date(b.reviewedAt));\n}\n\nexport async function removePendingReview(reviewId) {\n  const db = await openDb();\n  await runTx(db, PENDING_REVIEWS_STORE, \"readwrite\", (store) => store.delete(reviewId));\n}\n\nexport async function pendingReviewCount() {\n  return (await listPendingReviews()).length;\n}\n\n/** Caches the last good response for a GET path, keyed by the path itself\n * (including its query string, so `/sync/due?deck=Ukrainian` and `/sync/due` are\n * cached separately). Not a generic HTTP cache — just enough to redraw the last\n * known screen when a fetch fails outright. */\nexport async function cacheResponse(key, value) {\n  const db = await openDb();\n  await runTx(db, CACHE_STORE, \"readwrite\", (store) => store.put({ key, value }));\n}\n\nexport async function getCachedResponse(key) {\n  const db = await openDb();\n  const row = await new Promise((resolve, reject) => {\n    const req = db.transaction(CACHE_STORE, \"readonly\").objectStore(CACHE_STORE).get(key);\n    req.onsuccess = () => resolve(req.result);\n    req.onerror = () => reject(req.error);\n  });\n  return row?.value;\n}\n", contentType: "text/javascript; charset=utf-8" },
  "sw.js": { content: "// Service worker (step 3, docs/DESIGN.md §6) — caches the static app shell so the\n// page itself loads offline. Deliberately does not touch `/sync/*`: API data\n// freshness/queuing is `offline.js`'s job (an explicit IndexedDB cache + review\n// queue app.js reads from), not something to fake via an HTTP cache that could\n// silently serve stale due-queue data as if it were current.\n\nconst CACHE_NAME = \"capybara-anki-shell-v4\";\n// Served BY a Supabase Edge Function (`app`) — every real path lives under\n// /functions/v1/app/, never bare root (see app.js's own comment on this). These\n// are absolute from origin root, not relative to sw.js's own scope, because\n// that's what `cache.addAll` needs regardless of where this file itself sits.\nconst SHELL_FILES = [\n  \"/functions/v1/app/\",\n  \"/functions/v1/app/index.html\",\n  \"/functions/v1/app/app.js\",\n  \"/functions/v1/app/offline.js\",\n  \"/functions/v1/app/auth.js\",\n  \"/functions/v1/app/theme.css\",\n  \"/functions/v1/app/scan.html\",\n  \"/functions/v1/app/scan.js\",\n  \"/functions/v1/app/stats.html\",\n  \"/functions/v1/app/stats.js\",\n];\n\nself.addEventListener(\"install\", (event) => {\n  event.waitUntil(\n    caches.open(CACHE_NAME).then((cache) => cache.addAll(SHELL_FILES)).then(() => self.skipWaiting()),\n  );\n});\n\nself.addEventListener(\"activate\", (event) => {\n  event.waitUntil(\n    caches.keys()\n      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k))))\n      .then(() => self.clients.claim()),\n  );\n});\n\nself.addEventListener(\"fetch\", (event) => {\n  const url = new URL(event.request.url);\n  // Never intercept API calls — /scan (the Claude call) and /pronounce (the\n  // Whisper call, D18) need network as much as /sync does, and a cache-first\n  // match against a POST it never cached would only paper over that rather than\n  // fail honestly.\n  if (\n    url.pathname.startsWith(\"/functions/v1/sync\") || url.pathname.startsWith(\"/functions/v1/scan\") ||\n    url.pathname.startsWith(\"/functions/v1/pronounce\")\n  ) return;\n\n  event.respondWith(\n    caches.match(event.request).then((cached) => cached ?? fetch(event.request)),\n  );\n});\n", contentType: "text/javascript; charset=utf-8" },
  "theme.css": { content: "/* Shared across every page in web/ (index.html, scan.html) — the AnkiDroid-matched\n * palette and the toolbar chrome that looks identical wherever it appears.\n * Page-specific layout (deck list, card, rating row, scan results, …) stays in\n * each page's own <style> block; this file is only what would otherwise be copied\n * verbatim into a second <style> block and drift the first time one page's colors\n * changed and the other's didn't. */\n:root {\n  color-scheme: light dark;\n  --bg-page: #fdfdfd;\n  --bg-toolbar: #f5f5f5;\n  --bg-card: #fdfdfd;\n  --fg: #1b1b1b;\n  --fg-muted: #6b6b6b;\n  --border: #e0e0e0;\n  --stat-new: #3b6ea5;\n  --stat-learning: #c0392b;\n  --stat-review: #1e8e5a;\n  --btn-again: #c0392b;\n  --btn-hard-bg: #ececeb;\n  --btn-hard-fg: #8a6116;\n  --btn-good: #1e8e5a;\n  --btn-easy: #2471a3;\n  --btn-reveal: #3b4a5a;\n  --btn-fg: #ffffff;\n}\n@media (prefers-color-scheme: dark) {\n  :root {\n    --bg-page: #17181a;\n    --bg-toolbar: #232428;\n    --bg-card: #1c1d20;\n    --fg: #e8e8ea;\n    --fg-muted: #8b8b90;\n    --border: #35363a;\n    --stat-new: #6ea3e8;\n    --stat-learning: #e0685c;\n    --stat-review: #4fbf8a;\n    --btn-again: #b23a2d;\n    --btn-hard-bg: #2c2d31;\n    --btn-hard-fg: #d9a441;\n    --btn-good: #2e7d4f;\n    --btn-easy: #2e6da4;\n    --btn-reveal: #38424f;\n    --btn-fg: #ffffff;\n  }\n}\n* { box-sizing: border-box; }\nbody {\n  margin: 0;\n  font-family: -apple-system, system-ui, sans-serif;\n  background: var(--bg-page);\n  color: var(--fg);\n  min-height: 100vh;\n}\n#toolbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 14px 16px;\n  background: var(--bg-toolbar);\n  border-bottom: 1px solid var(--border);\n}\n#toolbar .icon-btn {\n  background: none;\n  border: none;\n  color: var(--fg);\n  font-size: 20px;\n  cursor: pointer;\n  padding: 4px 8px;\n  line-height: 1;\n  text-decoration: none;\n  display: inline-block;\n}\n/* `[hidden]` has to win over the `display` set above — a bare `.icon-btn` rule at\n * this specificity otherwise overrides the `hidden` attribute's own UA-stylesheet\n * `display: none`, which is exactly what silently broke back-button hiding the\n * first time this was written (caught by a Playwright screenshot showing \"←\" on\n * the deck-list screen where it should never appear). */\n#toolbar .icon-btn[hidden] { display: none; }\n#toolbar h1 { font-size: 17px; margin: 0; font-weight: 600; }\nmain { max-width: 480px; margin: 0 auto; padding: 0 16px; }\n\n/* Shared new/learning/review color convention — index.html's stats strip and\n * deck-list counts, and stats.html's collection-composition blocks all use these\n * same three classes, so the rule has to apply to the class alone, not scoped to\n * one container (a bug the first render of this caught: scoped to #stats-strip\n * only, the deck list's identical spans rendered with no color at all). */\n.new { color: var(--stat-new); }\n.learning { color: var(--stat-learning); }\n.review { color: var(--stat-review); }\n/* A queued-but-not-yet-synced review count (offline, step 3 §6) — deliberately\n * not one of the three colors above, since it isn't a due-queue bucket. */\n.pending { color: var(--fg-muted); margin-left: auto; }\n", contentType: "text/css; charset=utf-8" },
  "scan.html": { content: "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>Capybara — Scan</title>\n<link rel=\"stylesheet\" href=\"theme.css\" />\n<style>\n  /* Page-specific; the palette and toolbar chrome come from theme.css. */\n  #capture-label {\n    display: block;\n    margin: 24px 0;\n    padding: 22px;\n    text-align: center;\n    border: 2px dashed var(--border);\n    border-radius: 10px;\n    color: var(--fg-muted);\n    font-size: 16px;\n    cursor: pointer;\n  }\n  #capture-label:active { background: var(--bg-toolbar); }\n  #status {\n    text-align: center;\n    color: var(--fg-muted);\n    font-size: 14px;\n    padding: 8px 0;\n  }\n  .scan-result {\n    border: 1px solid var(--border);\n    border-radius: 8px;\n    padding: 12px 14px;\n    margin-bottom: 12px;\n  }\n  .scan-result-label {\n    font-size: 13px;\n    color: var(--fg-muted);\n    margin-bottom: 4px;\n    word-break: break-all;\n  }\n  .scan-result-counts { font-size: 15px; font-variant-numeric: tabular-nums; }\n  .scan-result-counts .imported { color: var(--stat-review); font-weight: 600; }\n  .scan-result-counts .rejected { color: var(--fg-muted); margin-left: 10px; }\n  .scan-result.scan-error .scan-result-counts { color: var(--btn-again); }\n  .scan-card { font-size: 14px; padding: 4px 0 0; border-top: 1px solid var(--border); margin-top: 6px; }\n  .scan-card:first-of-type { border-top: none; margin-top: 2px; }\n  #empty-hint { text-align: center; color: var(--fg-muted); padding: 40px 16px; }\n</style>\n</head>\n<body>\n<div id=\"toolbar\">\n  <a href=\"./\" class=\"icon-btn\">←</a>\n  <h1>Scan a page</h1>\n  <span style=\"width: 28px\"></span>\n</div>\n<main>\n  <label id=\"capture-label\" for=\"file-input\">📷 Take or choose photos of a highlighted page</label>\n  <input type=\"file\" id=\"file-input\" accept=\"image/*\" capture=\"environment\" multiple hidden />\n  <div id=\"status\" hidden></div>\n  <div id=\"results\"></div>\n  <div id=\"empty-hint\">Photograph a book page with yellow-highlighted words. Cards land straight in your Ukrainian deck — no export, no import.</div>\n</main>\n<script type=\"module\" src=\"scan.js\"></script>\n</body>\n</html>\n", contentType: "text/html; charset=utf-8" },
  "scan.js": { content: "// The scanner — step 5 of docs/DESIGN.md's build order (§4.1, §9). Replaces\n// ukrainian-anki-scanner's upload-photos-download-a-file flow: take/choose photos\n// here, and the extracted cards land directly in the deck (D10 — no ingest review\n// step; `index.html`'s Edit is the repair path for anything wrong).\n//\n// D8 (image prep in the browser): EXIF orientation and downscaling happen here via\n// `createImageBitmap` (which applies EXIF rotation itself) and a canvas resize,\n// mirroring claude_parser.py's own `optimize_image` — same target edge (1568px,\n// the size the API downscales to server-side anyway) and JPEG quality (0.85).\n//\n// Deliberately sequential, not the Python app's ThreadPoolExecutor(3): a typical\n// session is a handful of pages, each already taking several seconds of model\n// time, and sequential processing means deterministic per-photo result ordering\n// with no progress-bar bookkeeping to get right.\n\nimport { captureTokenFromUrl, getToken } from \"./auth.js\";\n\n// See app.js's own comment on this — Supabase Edge Functions only ever answer\n// under /functions/v1/<slug>, never bare root.\nconst API_BASE = \"/functions/v1\";\n\nconst MAX_IMAGE_EDGE = 1568;\nconst JPEG_QUALITY = 0.85;\n\nconst fileInput = document.getElementById(\"file-input\");\nconst statusEl = document.getElementById(\"status\");\nconst resultsEl = document.getElementById(\"results\");\nconst emptyHint = document.getElementById(\"empty-hint\");\n\nfunction escapeHtml(s) {\n  return (s ?? \"\").replace(/[&<>\"']/g, (c) => ({\n    \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\",\n  }[c]));\n}\n\n/** Orients and downscales a camera photo to a base64 JPEG, entirely client-side —\n * the browser never uploads a 12MB original over mobile data (D8). */\nasync function toJpegBase64(file) {\n  const bitmap = await createImageBitmap(file); // applies EXIF orientation itself\n  const scale = Math.min(1, MAX_IMAGE_EDGE / Math.max(bitmap.width, bitmap.height));\n  const canvas = document.createElement(\"canvas\");\n  canvas.width = Math.round(bitmap.width * scale);\n  canvas.height = Math.round(bitmap.height * scale);\n  canvas.getContext(\"2d\").drawImage(bitmap, 0, 0, canvas.width, canvas.height);\n\n  const blob = await new Promise((resolve) => canvas.toBlob(resolve, \"image/jpeg\", JPEG_QUALITY));\n  const dataUrl = await new Promise((resolve, reject) => {\n    const reader = new FileReader();\n    reader.onload = () => resolve(reader.result);\n    reader.onerror = () => reject(reader.error);\n    reader.readAsDataURL(blob);\n  });\n  return dataUrl.slice(dataUrl.indexOf(\",\") + 1); // drop the \"data:image/jpeg;base64,\" prefix\n}\n\nasync function scanFile(file) {\n  const imageBase64 = await toJpegBase64(file);\n  const res = await fetch(API_BASE + \"/scan/page\", {\n    method: \"POST\",\n    headers: { \"content-type\": \"application/json\", authorization: `Bearer ${getToken()}` },\n    body: JSON.stringify({ imageBase64, mediaType: \"image/jpeg\" }),\n  });\n  const data = await res.json();\n  if (!res.ok) throw new Error(data.error ?? `Scan failed (${res.status})`);\n  return data; // { imported, rejected } — src/scan/import.ts's ImportResult\n}\n\nfunction renderResult(label, result) {\n  emptyHint.hidden = true;\n  const row = document.createElement(\"div\");\n  row.className = \"scan-result\";\n  row.innerHTML = `\n    <div class=\"scan-result-label\">${escapeHtml(label)}</div>\n    <div class=\"scan-result-counts\">\n      <span class=\"imported\">+${result.imported.length}</span>\n      ${result.rejected.length ? `<span class=\"rejected\">${result.rejected.length} skipped</span>` : \"\"}\n    </div>\n    ${\n      result.imported\n        .map((c) => `<div class=\"scan-card\">${escapeHtml(c.lemma)} — ${escapeHtml(c.lemmaTranslation)}</div>`)\n        .join(\"\")\n    }\n  `;\n  resultsEl.prepend(row);\n  return row;\n}\n\nfunction renderError(label, message) {\n  const row = renderResult(label, { imported: [], rejected: [] });\n  row.classList.add(\"scan-error\");\n  row.querySelector(\".scan-result-counts\").textContent = message;\n}\n\nfileInput.addEventListener(\"change\", async () => {\n  const files = [...fileInput.files];\n  fileInput.value = \"\"; // lets the same file be re-selected later\n  if (!files.length) return;\n\n  statusEl.hidden = false;\n  for (const [i, file] of files.entries()) {\n    statusEl.textContent = `Processing photo ${i + 1} of ${files.length}…`;\n    try {\n      renderResult(file.name, await scanFile(file));\n    } catch (e) {\n      console.error(e);\n      renderError(file.name, e.message);\n    }\n  }\n  statusEl.hidden = true;\n});\n\ncaptureTokenFromUrl();\nif (!getToken()) {\n  document.body.innerHTML = `<div id=\"error\" style=\"text-align:center;padding:60px 16px;color:var(--fg-muted)\">No access token. Open your install link again.</div>`;\n}\n", contentType: "text/javascript; charset=utf-8" },
  "stats.html": { content: "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>Capybara — Stats</title>\n<link rel=\"stylesheet\" href=\"theme.css\" />\n<style>\n  /* Page-specific; the palette and toolbar chrome come from theme.css. */\n  .stat-row {\n    display: flex;\n    justify-content: space-between;\n    padding: 14px 0;\n    border-bottom: 1px solid var(--border);\n  }\n  .stat-label { color: var(--fg-muted); font-size: 14px; }\n  .stat-value { font-size: 20px; font-weight: 600; font-variant-numeric: tabular-nums; }\n\n  #chart-title { font-size: 14px; color: var(--fg-muted); margin: 24px 0 8px; }\n  #chart {\n    display: flex;\n    align-items: flex-end;\n    gap: 3px;\n    height: 140px;\n    border-bottom: 1px solid var(--border);\n  }\n  .chart-bar {\n    flex: 1;\n    display: flex;\n    flex-direction: column-reverse;\n    min-width: 2px;\n  }\n  .chart-bar div { width: 100%; }\n  .chart-bar .seg-again { background: var(--btn-again); }\n  .chart-bar .seg-hard { background: var(--btn-hard-fg); }\n  .chart-bar .seg-good { background: var(--btn-good); }\n  .chart-bar .seg-easy { background: var(--btn-easy); }\n  #chart-range { display: flex; justify-content: space-between; font-size: 11px; color: var(--fg-muted); margin-top: 4px; }\n\n  #composition { display: flex; gap: 10px; margin-top: 24px; }\n  .comp-block { flex: 1; text-align: center; padding: 12px 4px; border-radius: 8px; background: var(--bg-toolbar); }\n  .comp-count { font-size: 20px; font-weight: 600; font-variant-numeric: tabular-nums; }\n  .comp-label { font-size: 12px; color: var(--fg-muted); margin-top: 2px; }\n</style>\n</head>\n<body>\n<div id=\"toolbar\">\n  <a href=\"./\" class=\"icon-btn\">←</a>\n  <h1>Stats</h1>\n  <span style=\"width: 28px\"></span>\n</div>\n<main>\n  <div id=\"content\"><div style=\"padding: 40px; text-align: center; color: var(--fg-muted)\">Loading…</div></div>\n</main>\n<script type=\"module\" src=\"stats.js\"></script>\n</body>\n</html>\n", contentType: "text/html; charset=utf-8" },
  "stats.js": { content: "// The stats screen — step 6 of docs/DESIGN.md's build order. Plain JS, no build\n// step, same as every other page in web/: fetch /sync/stats, render four things\n// (streak, success rate, total reviews, a day-by-day activity chart) plus the\n// collection's current state composition.\n\nimport { captureTokenFromUrl, getToken } from \"./auth.js\";\n\n// See app.js's own comment on this — Supabase Edge Functions only ever answer\n// under /functions/v1/<slug>, never bare root.\nconst API_BASE = \"/functions/v1\";\n\nconst contentEl = document.getElementById(\"content\");\n\nasync function api(path) {\n  const res = await fetch(API_BASE + path, { headers: { authorization: `Bearer ${getToken()}` } });\n  if (!res.ok) throw new Error(`GET ${path} -> ${res.status}`);\n  return res.json();\n}\n\nfunction formatPercent(fraction) {\n  return fraction === null ? \"—\" : `${Math.round(fraction * 100)}%`;\n}\n\n/** A stacked bar per day, each bar's height relative to the busiest day in the\n * window (not to a fixed scale) — so a quiet week doesn't render as a flat line\n * and a heavy one doesn't clip. Segments within a bar are relative to that day's\n * own total, using the same Again/Hard/Good/Easy colors as the reviewer's rating\n * buttons (theme.css's --btn-* tokens) so the chart reads the same language. */\nfunction renderChart(days) {\n  const maxTotal = Math.max(1, ...days.map((d) => d.again + d.hard + d.good + d.easy));\n  const bars = days.map((d) => {\n    const total = d.again + d.hard + d.good + d.easy;\n    const barPct = (total / maxTotal) * 100;\n    const segPct = (n) => (total > 0 ? (n / total) * 100 : 0);\n    return `\n      <div class=\"chart-bar\" style=\"height:${barPct}%\" title=\"${d.date}: ${total} review${total === 1 ? \"\" : \"s\"}\">\n        <div class=\"seg-again\" style=\"height:${segPct(d.again)}%\"></div>\n        <div class=\"seg-hard\" style=\"height:${segPct(d.hard)}%\"></div>\n        <div class=\"seg-good\" style=\"height:${segPct(d.good)}%\"></div>\n        <div class=\"seg-easy\" style=\"height:${segPct(d.easy)}%\"></div>\n      </div>\n    `;\n  }).join(\"\");\n  return `\n    <div id=\"chart\">${bars}</div>\n    <div id=\"chart-range\">\n      <span>${days[0]?.date ?? \"\"}</span>\n      <span>${days[days.length - 1]?.date ?? \"\"}</span>\n    </div>\n  `;\n}\n\nfunction render(stats) {\n  contentEl.innerHTML = `\n    <div class=\"stat-row\">\n      <span class=\"stat-label\">Current streak</span>\n      <span class=\"stat-value\">${stats.currentStreak} day${stats.currentStreak === 1 ? \"\" : \"s\"}</span>\n    </div>\n    <div class=\"stat-row\">\n      <span class=\"stat-label\">Success rate</span>\n      <span class=\"stat-value\">${formatPercent(stats.successRate)}</span>\n    </div>\n    <div class=\"stat-row\">\n      <span class=\"stat-label\">Total reviews</span>\n      <span class=\"stat-value\">${stats.totalReviews}</span>\n    </div>\n    <div id=\"chart-title\">Last ${stats.reviewsByDay.length} days</div>\n    ${renderChart(stats.reviewsByDay)}\n    <div id=\"composition\">\n      <div class=\"comp-block\"><div class=\"comp-count new\">${stats.cardCounts.newCount}</div><div class=\"comp-label\">New</div></div>\n      <div class=\"comp-block\"><div class=\"comp-count learning\">${stats.cardCounts.learningCount}</div><div class=\"comp-label\">Learning</div></div>\n      <div class=\"comp-block\"><div class=\"comp-count review\">${stats.cardCounts.reviewCount}</div><div class=\"comp-label\">Review</div></div>\n      <div class=\"comp-block\"><div class=\"comp-count\">${stats.cardCounts.suspendedCount}</div><div class=\"comp-label\">Suspended</div></div>\n    </div>\n  `;\n}\n\nasync function main() {\n  captureTokenFromUrl();\n  if (!getToken()) {\n    contentEl.innerHTML = `<div id=\"error\">No access token. Open your install link again.</div>`;\n    return;\n  }\n  try {\n    render(await api(\"/sync/stats\"));\n  } catch (e) {\n    contentEl.innerHTML = `<div id=\"error\">Couldn't load stats.</div>`;\n    console.error(e);\n  }\n}\n\nmain();\n", contentType: "text/javascript; charset=utf-8" },
};

Deno.serve((req) => {
  const url = new URL(req.url);
  if (req.method !== "GET" && req.method !== "HEAD") {
    return new Response("method not allowed", { status: 405 });
  }

  let path = url.pathname.replace(/^\/app\/?/, "");
  if (path === "") path = "index.html";

  const file = FILES[path];
  if (!file) return new Response("not found", { status: 404 });
  return new Response(req.method === "HEAD" ? null : file.content, {
    headers: { "content-type": file.contentType },
  });
});
